def check_files():
    """several small text files must exist and satisfy line-level constraints"""
    s = 0.0
    n = 0
    for f in SPEC["files"]:
        n += 1
        if not os.path.exists(f["path"]):
            notes.append(f"{f['path']}: not found")
            continue
        text = open(f["path"], encoding="utf-8", errors="replace").read()
